CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'reader',last_seen TEXT,created_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE topics(id TEXT PRIMARY KEY,name TEXT NOT NULL,color TEXT NOT NULL,parent_id TEXT REFERENCES topics(id) ON DELETE SET NULL,keywords TEXT NOT NULL DEFAULT '[]',exclusions TEXT NOT NULL DEFAULT '[]',description TEXT NOT NULL DEFAULT '');
CREATE TABLE sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',url TEXT NOT NULL UNIQUE,type TEXT NOT NULL,topics TEXT NOT NULL DEFAULT '[]',priority INTEGER NOT NULL DEFAULT 5,interval_minutes INTEGER NOT NULL DEFAULT 30,enabled INTEGER NOT NULL DEFAULT 1,rights_confirmed INTEGER NOT NULL DEFAULT 0,last_success TEXT,last_attempt TEXT,next_run TEXT NOT NULL,lease_until TEXT,lease_token TEXT,status TEXT NOT NULL DEFAULT 'pending',error TEXT,failures INTEGER NOT NULL DEFAULT 0,item_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE clusters(id TEXT PRIMARY KEY,title TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE articles(id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(id) ON DELETE SET NULL,source_name TEXT NOT NULL,url TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',content TEXT NOT NULL DEFAULT '',author TEXT,published_at TEXT,fetched_at TEXT NOT NULL,updated_at TEXT NOT NULL,content_hash TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',relevance INTEGER NOT NULL DEFAULT 5,fact_status TEXT NOT NULL DEFAULT 'Einzelbericht',fact_note TEXT NOT NULL DEFAULT 'Nicht unabhängig überprüft.',cluster_id TEXT REFERENCES clusters(id),ai_status TEXT NOT NULL DEFAULT 'pending',ai_attempts INTEGER NOT NULL DEFAULT 0,ai_next_run TEXT,ai_error TEXT,manual_topics INTEGER NOT NULL DEFAULT 0,media_type TEXT);
CREATE TABLE article_topics(article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,topic_id TEXT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,PRIMARY KEY(article_id,topic_id));
CREATE TABLE revisions(id TEXT PRIMARY KEY,article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,title TEXT NOT NULL,content TEXT NOT NULL,changed_at TEXT NOT NULL,change_note TEXT NOT NULL);
CREATE TABLE analyses(id TEXT PRIMARY KEY,article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,model TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE fetch_logs(id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(id) ON DELETE SET NULL,source_name TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT NOT NULL,status TEXT NOT NULL,found INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE TABLE favorites(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,PRIMARY KEY(user_id,article_id));
CREATE TABLE notification_rules(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,topic_id TEXT REFERENCES topics(id) ON DELETE CASCADE,min_relevance INTEGER NOT NULL DEFAULT 8,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_run TEXT,error TEXT,created_at TEXT NOT NULL,UNIQUE(user_id,article_id));
CREATE TABLE briefings(id TEXT PRIMARY KEY,day TEXT NOT NULL UNIQUE,content TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE worker_locks(name TEXT PRIMARY KEY,token TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX sources_due ON sources(enabled,next_run,lease_until);
CREATE INDEX articles_dates ON articles(fetched_at,updated_at);
CREATE INDEX articles_cluster ON articles(cluster_id);
CREATE INDEX articles_ai ON articles(ai_status,ai_next_run);
CREATE INDEX articles_relevance ON articles(relevance);
CREATE INDEX article_topics_topic ON article_topics(topic_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
